import{_ as o,o as t,c as r,a2 as a}from"./chunks/framework.BN3Eol-0.js";const p=JSON.parse('{"title":"ADR-097 — No staging tier: releases go straight to prod, GitHub Pages serves only the docs","description":"","frontmatter":{},"headers":[],"relativePath":"adr/ADR-097.md","filePath":"adr/ADR-097.md"}'),d={name:"adr/ADR-097.md"};function s(i,e,n,c,l,h){return t(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="adr-097-—-no-staging-tier-releases-go-straight-to-prod-github-pages-serves-only-the-docs" tabindex="-1">ADR-097 — No staging tier: releases go straight to prod, GitHub Pages serves only the docs <a class="header-anchor" href="#adr-097-—-no-staging-tier-releases-go-straight-to-prod-github-pages-serves-only-the-docs" aria-label="Permalink to &quot;ADR-097 — No staging tier: releases go straight to prod, GitHub Pages serves only the docs&quot;">​</a></h1><blockquote><p>Status · Accepted · 2026-11-10 (operator) · supersedes the staging parts of <strong>ADR-014</strong> (GitHub Pages as preview environment), <strong>ADR-070</strong> / <strong>ADR-071</strong> (the app+docs publisher chained off docker-e2e), <strong>ADR-082</strong> (the dev → staging → prod ladder) and <strong>ADR-083</strong> (the mobile staging↔prod switcher)</p></blockquote><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>Since July 2026 the app had three tiers: dev, staging (the app bundle on GitHub Pages at <code>chipi.github.io/orrery</code>, published by <code>staging.yml</code> after every green docker-e2e, smoked by <code>validate-staging.yml</code>) and prod (the self-hosted VPS, <code>deploy-prod.yml</code>, manual).</p><p>Staging stopped earning its cost:</p><ul><li>Pages is a different host from prod: no nginx headers or CSP, a <code>/orrery/</code> base path, no <code>/data</code> overlay. The staging smoke skipped the checks that matter for prod and could pass while prod broke.</li><li>The app copy on Pages was a divergent, SEO-duplicate mirror (RFC-035, ADR-096 noindex) and a ~2.5 GB bundle on the <code>gh-pages</code> branch.</li><li>Two telemetry rungs, two GitHub environments and a mobile switcher existed only to feed it.</li><li>Every release already needed <code>validate-prod</code> on the real host, so staging was a second, weaker validation in front of the first.</li></ul><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><ol><li><strong>There is no staging tier.</strong> The release flow is: merge to <code>main</code> → <code>gh workflow run &quot;Deploy to prod VPS (orrery)&quot; --ref main</code> → validate-prod (the deploy&#39;s own <code>validate</code> job, then <code>validate-prod.yml</code> on its completion and daily). The deploy stays manual; dispatch it only for a commit whose <code>ci.yml</code> and docker-e2e runs are green.</li><li><strong>GitHub Pages serves only the project docs.</strong> <code>deploy-docs.yml</code> (CI-gated, ADR-070) publishes the whole <code>gh-pages</code> tree: a static root page forwarding to <code>https://www.orrerylearn.com/</code> (<code>docs/.vitepress/gh-pages-root/index.html</code>) plus the VitePress build under <code>docs/</code>, so <code>/orrery/docs/</code> URLs keep working. It no longer relies on <code>keep_files</code> to preserve an app bundle.</li><li><strong><code>staging.yml</code> (&quot;Deploy preview&quot;) and <code>validate-staging.yml</code> are deleted.</strong></li><li><strong>The app drops the staging tier.</strong> <code>src/lib/target-env.ts</code>, its test, <code>TargetEnvSwitcher.svelte</code> and the <code>__MOBILE_INTERNAL__</code> define are removed; <code>sentry.ts</code>, <code>analytics.ts</code> and <code>asset-url.ts</code> read the env ladder (dev, prod) and <code>STREAM_ORIGIN</code> directly. <code>STREAM_ORIGIN</code> defaults to <code>https://www.orrerylearn.com</code>.</li><li><strong>Telemetry is two rungs</strong> (prod, dev). The staging GlitchTip project (6) and Umami site (<code>6e7ddfce…</code>) receive nothing new.</li></ol><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>A bad commit is found on prod, not before it. The mitigations are the green-CI rule in the flow, <code>validate-prod</code> right after the deploy, and the rollback in <code>docs/ops/deploy-prod-vps.md</code>.</li><li>The first <code>deploy-docs.yml</code> run after this change replaces the <code>gh-pages</code> tree, which removes the app bundle from the branch tip. The history keeps the blobs; shrinking the branch is a separate, operator-approved step.</li><li>Mobile builds stream pruned assets from the prod origin by default.</li><li><code>scripts/validate-prod.mjs</code> keeps an unused <code>VALIDATE_TIER</code> knob.</li></ul><h2 id="not-covered" tabindex="-1">Not covered <a class="header-anchor" href="#not-covered" aria-label="Permalink to &quot;Not covered&quot;">​</a></h2><ul><li>Deleting the staging GlitchTip project, the Umami site and the <code>staging</code> GitHub environment.</li><li>Rewriting ADR history: ADR-014, 067, 070, 071, 082 and 083 carry a &quot;superseded&quot; note and are otherwise unchanged.</li></ul>',12)])])}const u=o(d,[["render",s]]);export{p as __pageData,u as default};
